import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Paper,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import SendIcon from '@mui/icons-material/Send';
import SmartToyOutlinedIcon from '@mui/icons-material/SmartToyOutlined';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import ApiService from '../services/api';
import useAppTranslation from '../hooks/useAppTranslation';

type ChatRole = 'user' | 'assistant';

type ChatMessage = {
  id: string;
  role: ChatRole;
  text: string;
  suggestedRoute?: string | null;
  intent?: string | null;
  sources?: string[];
};

const SUGGESTED_PROMPTS = [
  'How much water did we save this month?',
  'Why did our carbon footprint increase?',
  'What are the three highest-impact actions?',
  'How much will we save if we install solar?',
  'Prepare our sustainability action plan for FY27.',
  'Find the cheapest way to reduce emissions by 20%.',
];

const createId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

/**
 * AI Advisor — organisation sustainability Q&A (footprint, water, hotspots, solar, plans).
 */
const CarbonCopilotPage: React.FC = () => {
  const { t } = useAppTranslation();
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>(() => [
    {
      id: createId(),
      role: 'assistant',
      text: t('copilot.welcome'),
    },
  ]);
  const listRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, loading]);

  const canSend = useMemo(() => input.trim().length > 0 && !loading, [input, loading]);

  const ask = async (rawMessage: string) => {
    const message = rawMessage.trim();
    if (!message || loading) return;

    setError(null);
    setInput('');
    setMessages((prev) => [...prev, { id: createId(), role: 'user', text: message }]);
    setLoading(true);

    try {
      const response = await ApiService.askCarbonCopilot(message);
      if (!response?.success) {
        throw new Error(response?.message || t('copilot.questionFailed'));
      }
      const payload = (response.data || {}) as {
        answer?: string;
        reply?: string;
        suggestedRoute?: string;
        intent?: string;
        sources?: string[];
      };
      const answer = String(payload.answer || payload.reply || '').trim() || t('copilot.noAnswer');
      setMessages((prev) => [
        ...prev,
        {
          id: createId(),
          role: 'assistant',
          text: answer,
          suggestedRoute: payload.suggestedRoute || null,
          intent: payload.intent || null,
          sources: payload.sources || [],
        },
      ]);
    } catch (err) {
      setError(err instanceof Error ? err.message : t('copilot.questionFailed'));
      setMessages((prev) => [
        ...prev,
        {
          id: createId(),
          role: 'assistant',
          text: t('copilot.questionFailed'),
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box data-testid="ai-advisor-page">
      <WorkspacePageHeader
        title={t('copilot.title')}
        description={t('copilot.subtitle')}
      />

      <Stack spacing={2}>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
          {SUGGESTED_PROMPTS.map((prompt) => (
            <Chip
              key={prompt}
              label={prompt}
              clickable
              disabled={loading}
              onClick={() => void ask(prompt)}
              variant="outlined"
              size="small"
            />
          ))}
        </Stack>

        {error ? <Alert severity="error">{error}</Alert> : null}

        <Paper
          variant="outlined"
          sx={{
            height: { xs: 420, md: 520 },
            display: 'flex',
            flexDirection: 'column',
            overflow: 'hidden',
          }}
        >
          <Box
            ref={listRef}
            sx={{
              flex: 1,
              overflowY: 'auto',
              p: 2,
              bgcolor: 'action.hover',
            }}
          >
            <Stack spacing={1.5}>
              {messages.map((message) => {
                const isUser = message.role === 'user';
                return (
                  <Box
                    key={message.id}
                    sx={{
                      display: 'flex',
                      justifyContent: isUser ? 'flex-end' : 'flex-start',
                    }}
                  >
                    <Box
                      sx={{
                        maxWidth: { xs: '92%', md: '75%' },
                        px: 1.5,
                        py: 1.25,
                        borderRadius: 2,
                        bgcolor: isUser ? 'primary.main' : 'background.paper',
                        color: isUser ? 'primary.contrastText' : 'text.primary',
                        border: isUser ? 'none' : '1px solid',
                        borderColor: 'divider',
                      }}
                    >
                      {!isUser ? (
                        <Stack direction="row" spacing={0.75} alignItems="center" sx={{ mb: 0.5 }}>
                          <SmartToyOutlinedIcon fontSize="small" color="primary" />
                          <Typography variant="caption" color="text.secondary">
                            {t('copilot.title')}
                          </Typography>
                        </Stack>
                      ) : null}
                      <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', lineHeight: 1.55 }}>
                        {message.text}
                      </Typography>
                      {message.suggestedRoute ? (
                        <Button
                          component={RouterLink}
                          to={message.suggestedRoute}
                          size="small"
                          sx={{ mt: 1 }}
                          variant="text"
                        >
                          {t('copilot.openSuggested')}
                        </Button>
                      ) : null}
                    </Box>
                  </Box>
                );
              })}
              {loading ? (
                <Stack direction="row" spacing={1} alignItems="center">
                  <CircularProgress size={16} />
                  <Typography variant="caption" color="text.secondary">
                    {t('copilot.thinking')}
                  </Typography>
                </Stack>
              ) : null}
            </Stack>
          </Box>

          <Box sx={{ p: 1.5, borderTop: '1px solid', borderColor: 'divider' }}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <TextField
                fullWidth
                size="small"
                label={t('copilot.questionLabel')}
                placeholder={t('copilot.questionPlaceholder')}
                value={input}
                onChange={(event) => setInput(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === 'Enter' && !event.shiftKey) {
                    event.preventDefault();
                    void ask(input);
                  }
                }}
                disabled={loading}
                multiline
                maxRows={3}
              />
              <Button
                variant="contained"
                startIcon={loading ? <CircularProgress size={16} color="inherit" /> : <SendIcon />}
                disabled={!canSend}
                onClick={() => void ask(input)}
                sx={{ minWidth: 120 }}
              >
                {t('copilot.ask')}
              </Button>
            </Stack>
          </Box>
        </Paper>
      </Stack>
    </Box>
  );
};

export default CarbonCopilotPage;
